const rssItems = $items('Fetch OpenTelemetry Blog').map(i => i.json);
const sheetItems = $items('Read Existing Tracker').map(i => i.json);
const existingUrls = new Set(sheetItems.map(item => (item.URL || item['Article ID'] || '').trim().replace(/\/$/, '')).filter(Boolean));
const newPosts = [];
for (const rss of rssItems) {
  const link = (rss.link || '').trim().replace(/\/$/, '');
  const title = (rss.title || '').trim();
  if (!link || !title) continue;
  if (!existingUrls.has(link)) {
    newPosts.push({json: {'Article ID': rss.link, Title: title, URL: rss.link, 'Published Date': rss.isoDate || rss.pubDate || '', score: 0, 'Score Reason': '', Status: 'Pending', Posted: 'FALSE', 'Posted Date': ''}});
  }
}
if (newPosts.length === 0) return [{json: {_no_new_items: true}}];
return newPosts;

const gemini = $input.first().json;
const original = $('Identify New Blog Posts').item.json;
let result = {};
try { const text = gemini.candidates?.[0]?.content?.parts?.[0]?.text || '{}'; result = JSON.parse(text); } catch (e) { result = {score: 5, reason: 'Gemini scoring response could not be parsed; default score applied.'}; }
let score = Number(result.score);
if (!Number.isFinite(score)) score = 5;
score = Math.max(1, Math.min(10, Math.round(score)));
return [{json: {...original, score, 'Score Reason': result.reason || '', Status: 'Pending', Posted: 'FALSE'}}];

const profileData = $items('Get LinkedIn Profile URN')[0].json;
const memberId = profileData.sub || profileData.id;
const authorUrn = `urn:li:person:${memberId}`;
const rows = $items('Read Updated Tracker');
const candidates = [];
for (const item of rows) {
  const row = item.json;
  const rawPosted = row.Posted;
  const isPosted = rawPosted === true || String(rawPosted || '').trim().toUpperCase() === 'TRUE';
  const title = (row.Title || '').trim();
  const url = (row.URL || row['Article ID'] || '').trim();
  const scoreValue = row.score ?? row.Score ?? 0;
  const score = Number(scoreValue);
  const pubDateStr = row['Published Date'] || '';
  const pubDate = pubDateStr ? new Date(pubDateStr).getTime() : 0;
  if (isPosted || !title || !url) continue;
  candidates.push({rowNumber: row.row_number, title, url, score: Number.isFinite(score) ? score : 0, pubDate: Number.isFinite(pubDate) ? pubDate : 0, author_urn: authorUrn});
}
if (candidates.length === 0) return [];
candidates.sort((a,b) => a.score !== b.score ? b.score - a.score : b.pubDate - a.pubDate);
return [{json: candidates[0]}];

const html = $input.first().json.data || '';
let cleanText = html.replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<nav[\s\S]*?<\/nav>/gi,' ').replace(/<footer[\s\S]*?<\/footer>/gi,' ').replace(/<header[\s\S]*?<\/header>/gi,' ').replace(/<[^>]*>/g,' ').replace(/&nbsp;/gi,' ').replace(/&amp;/gi,'&').replace(/&lt;/gi,'<').replace(/&gt;/gi,'>').replace(/&quot;/gi,'"').replace(/&#39;/gi,"'").replace(/\s+/g,' ').trim();
cleanText = cleanText.substring(0,20000);
return [{json: {...$('Filter Unposted & Pick Best').first().json, article_text: cleanText}}];

const geminiRes = $input.first().json;
const source = $('Clean HTML to Text').first().json;
let post = '';
try { const textContent = geminiRes.candidates?.[0]?.content?.parts?.[0]?.text || '{}'; const parsed = JSON.parse(textContent); post = String(parsed.linkedin_post || '').trim(); } catch (e) {}
if (!post) throw new Error('Gemini did not return a valid LinkedIn post. Publishing stopped.');
const wordCount = post.split(/\s+/).filter(Boolean).length;
if (wordCount < 120 || wordCount > 300) throw new Error(`Generated LinkedIn post has ${wordCount} words. Expected approximately 150-250. Publishing stopped.`);
if (!post.includes(source.url)) post += `\n\nRead the full article here: ${source.url}`;
if (!post.includes('#PerformanceEngineering')) post += '\n\n#PerformanceEngineering #Observability #DevOps #SRE #OpenTelemetry';
return [{json: {...source, linkedin_post: post}}];
